    oid,
    tid,
    username: typeof payload.preferred_username === "string" ? payload.preferred_username : "",
    roles: stringArray(payload.roles),
    groups: stringArray(payload.groups),
    scopes: typeof payload.scp === "string" ? payload.scp.split(" ") : [],
