  const encoded = request.headers.get("x-ms-client-principal");
  if (!encoded) {
    return undefined;
  }
  try {
    const decoded = JSON.parse(Buffer.from(encoded, "base64").toString("utf8")) as {
      auth_typ?: string;
      claims?: ClientPrincipalClaim[];
      role_typ?: string;
    };
