/**
 * Access helpers shared by the portal and desk controllers.
 *
 * The users-permissions plugin verifies the JWT and drops the bare user row on
 * ctx.state.user, but it will not populate our custom `organisation` relation,
 * so anything that needs to know which newsroom the caller belongs to has to
 * ask for it. API tokens arrive without a user at all - the desk cron jobs show
 * up on ctx.state.auth instead.
 */

export type Membership = {
  userId: number;
  userDocumentId: string;
  organisationId: string | null;
  organisationName: string | null;
  roleType: string | null;
};

const EDITORIAL_ROLE_TYPES = new Set(["editor", "managing_editor", "newsroom_admin"]);

export async function resolveMembership(ctx: any): Promise<Membership | null> {
  const sessionUser = ctx.state.user;
  if (!sessionUser?.documentId) {
    return null;
  }

  const account: any = await strapi
    .documents("plugin::users-permissions.user")
    .findOne({
      documentId: sessionUser.documentId,
      fields: ["username", "blocked"],
      populate: {
        role: { fields: ["type"] },
        organisation: { fields: ["name"] },
      },
    });

  if (!account || account.blocked) {
    return null;
  }

  return {
    userId: sessionUser.id,
    userDocumentId: sessionUser.documentId,
    organisationId: account.organisation?.documentId ?? null,
    organisationName: account.organisation?.name ?? null,
    roleType: account.role?.type ?? null,
  };
}

export function isEditorialStaff(membership: Membership | null): boolean {
  return Boolean(membership?.roleType && EDITORIAL_ROLE_TYPES.has(membership.roleType));
}

/**
 * The desk cron and the syndication worker talk to us with a full-access API
 * token rather than a session.
 */
export function isFullAccessToken(ctx: any): boolean {
  return (
    ctx.state.auth?.strategy?.name === "api-token" &&
    ctx.state.auth?.credentials?.type === "full-access"
  );
}

