/**
 * global::is-authenticated
 *
 * users-permissions already rejects a missing or expired JWT before the policy
 * chain runs; this one additionally bounces accounts that have been blocked
 * since their token was issued.
 */
export default (policyContext: any, _config: unknown, { strapi }: any) => {
  const user = policyContext.state.user;

  if (!user) {
    return false;
  }

  if (user.blocked) {
    strapi.log.warn(`blocked account ${user.id} hit ${policyContext.request.url}`);
    return false;
  }

  return true;
};

