/**
 * global::is-editorial-staff
 *
 * Guards the desk routes. Reads the role off the session user - the plugin
 * populates `role` on ctx.state.user, so no extra query is needed here.
 */
const EDITORIAL_ROLE_TYPES = ["editor", "managing_editor", "newsroom_admin"];

export default (policyContext: any, _config: unknown, { strapi }: any) => {
  const user = policyContext.state.user;

  if (!user) {
    return false;
  }

  if (!EDITORIAL_ROLE_TYPES.includes(user.role?.type)) {
    strapi.log.warn(`role ${user.role?.type} refused at ${policyContext.request.url}`);
    return false;
  }

  return true;
};

